await test('verificador acepta objeto directo válido',async()=>{let called='';const fetchImpl=async(url,options)=>{called=url;assert.equal(JSON.stringify(options).includes('LAB029_POSTGRES_URI'),false);return {status:200,json:async()=>verifierContract}};const out=await verificarEstado({manifestPath:prepared.manifest,checkpoint:'g01',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl});assert.equal(out.ok,true);assert.ok(called.includes('/webhook/lab029-test-'));});
for(const [name,body] of [['array de un item',[verifierContract]],['item json',{json:verifierContract}],['wrapper body',{body:verifierContract}],['JSON doblemente codificado',JSON.stringify(verifierContract)]])await test(`verificador acepta ${name}`,async()=>assert.equal((await verificarEstado({manifestPath:prepared.manifest,checkpoint:'g01',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl:async()=>({status:200,text:async()=>JSON.stringify(body)})})).ok,true));
for(const [name,response,pattern] of [['401',{status:401,text:async()=>''},/verifier_http_401/],['postgres 500',{status:500,text:async()=>'{"message":"Postgres node failed"}'},/verifier_http_500:verifier_postgres_failed/],['body vacío',{status:200,text:async()=>''},/verifier_body_empty/],['texto no JSON',{status:200,text:async()=>'<html>Error</html>'},/verifier_body_text_not_json/],['ok ausente',{status:200,text:async()=>'{"checkpoint":"g01"}'},/verifier_body_missing_ok/],['contrato incompleto',{status:200,text:async()=>'{"ok":true,"checkpoint":"g01","assertions":[]}'},/verifier_body_contract_invalid/],['assertion fallida',{status:409,text:async()=>'{"ok":false,"checkpoint":"g01","assertions":[{"name":"cero_residuos","ok":false}],"summary":{}}'},/assertions_verificador_fallidas:cero_residuos/]])await test(`diagnóstico verificador ${name}`,async()=>assert.rejects(()=>verificarEstado({manifestPath:prepared.manifest,checkpoint:'snapshot',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl:async()=>response}),pattern));
await test('orquestador bloquea ejecución sin confirmación',async()=>assert.rejects(()=>ejecutarRuntime({manifestPath:prepared.manifest,phase:'management',env,fetchImpl:runtimeFetch,verifyImpl:verifyMock}),/confirmacion_runtime_requerida/));
await test('management prepara clínicas antes de G-01',async()=>{const checkpoints=[];const out=await ejecutarRuntime({manifestPath:prepared.manifest,phase:'management',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl:runtimeFetch,verifyImpl:async({checkpoint})=>{checkpoints.push(checkpoint);return verifyMock({checkpoint});}});assert.equal(out.ok,true);assert.equal(checkpoints[0],'setup');assert.equal(checkpoints[1],'g01');});
await test('internal prepara identidades y exige subjects deterministas del run',async()=>{const checkpoints=[];const out=await ejecutarRuntime({manifestPath:prepared.manifest,phase:'internal',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl:runtimeFetch,verifyImpl:async({checkpoint})=>{checkpoints.push(checkpoint);return verifyMock({checkpoint});}});assert.equal(out.ok,true);assert.equal(checkpoints[0],'setup');await assert.rejects(()=>ejecutarRuntime({manifestPath:prepared.manifest,phase:'internal',confirm:'LAB029_RUNTIME_REAL',env:{...env,LAB029_IDENTITY_SUBJECT_A:'subject-ajeno'},fetchImpl:runtimeFetch,verifyImpl:verifyMock}),/LAB029_IDENTITY_SUBJECT_A_invalido/);});
await test('I-03 usa consulta ajena a los identificadores del run',async()=>{const manifest=JSON.parse(await readFile(prepared.manifest,'utf8'));let question='';const fetchImpl=async(url,options)=>{const body=JSON.parse(options.body);if(String(url).includes('interno')&&body.message?.includes('extintor'))question=body.message;return runtimeFetch(url,options);};const out=await ejecutarRuntime({manifestPath:prepared.manifest,phase:'internal',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl,verifyImpl:verifyMock});assert.equal(out.results.find(x=>x.id==='I-03').status,'PASS');assert.equal(question,'¿Cuál es el número de serie del extintor instalado en la bodega norte?');for(const identifier of [manifest.prefix,manifest.run_id,...Object.values(manifest.ids).filter(x=>typeof x==='string')])assert.equal(question.toLowerCase().includes(identifier.toLowerCase()),false);assert.equal(/LAB029_TEST/i.test(question),false);});
await test('--case=G-02 ejecuta setup, prepare_g02 y únicamente G-02',async()=>{const checkpoints=[];let requests=0;const out=await ejecutarRuntime({manifestPath:prepared.manifest,phase:'management',caseId:'G-02',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl:async(...args)=>{requests++;return runtimeFetch(...args);},verifyImpl:async({checkpoint})=>{checkpoints.push(checkpoint);return verifyMock({checkpoint});}});assert.equal(out.ok,true);assert.equal(out.case,'G-02');assert.deepEqual(out.results.map(x=>x.id),['G-02']);assert.deepEqual(checkpoints,['setup','prepare_g02','g02']);assert.equal(requests,1);});
for(const [phase,caseId,expectedCheckpoints] of [['internal','I-03',['setup']],['public','P-03',[]],['persistence','PS-01/I-01',[]]])await test(`--case=${caseId} ejecuta únicamente ese caso en ${phase}`,async()=>{const checkpoints=[];let requests=0;const out=await ejecutarRuntime({manifestPath:prepared.manifest,phase,caseId,confirm:'LAB029_RUNTIME_REAL',env,fetchImpl:async(...args)=>{requests++;return runtimeFetch(...args);},verifyImpl:async({checkpoint})=>{checkpoints.push(checkpoint);return verifyMock({checkpoint});}});assert.equal(out.ok,true);assert.equal(out.case,caseId);assert.deepEqual(out.results.map(x=>x.id),[caseId]);assert.deepEqual(checkpoints,expectedCheckpoints);assert.equal(requests,1);});
for(const [name,separator,source,expected] of [['espacio ASCII',' ',mockInternalDocId,'PASS'],['narrow no-break space','\u202f',mockInternalDocId,'PASS'],['no-break space','\u00a0',mockInternalDocId,'PASS'],['fuente incorrecta',' ','otro_documento','FAIL'],['fuente ausente',' ',null,'FAIL'],['dato interno ausente',null,mockInternalDocId,'FAIL']])await test(`PS-01/I-01 ${name}`,async()=>{const manifest=JSON.parse(await readFile(prepared.manifest,'utf8'));const message=separator===null?'No encontré información interna.':`El protocolo interno${separator}${manifest.run_id} corresponde al documento esperado.`;const fetchImpl=async()=>({status:200,json:async()=>({ok:true,action:'consulta_rag_interno',message,data:{fuentes:source?[source]:[]}})});const out=await ejecutarRuntime({manifestPath:prepared.manifest,phase:'persistence',caseId:'PS-01/I-01',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl,verifyImpl:verifyMock});assert.deepEqual(out.results.map(x=>x.id),['PS-01/I-01']);assert.equal(out.results[0].status,expected);});
await test('prepare_g02 queda restringido al documento público A exacto del run',async()=>{const workflow=JSON.parse(await readFile(join(prepared.directory,'workflow_verificador_runtime.json'),'utf8'));const pg=workflow.nodes.find(x=>x.type==='n8n-nodes-base.postgres'),query=pg.parameters.query,replacements=pg.parameters.options.queryReplacement;assert.match(query,/\$3='prepare_g02'/);assert.match(query,/\$1=lower\(\$7\)\|\|'_clinic_a'/);assert.match(query,/\$6=\$7\|\|'_DOC_PUBLIC_A'/);assert.match(query,/v\.status IN \('staging','failed'\)/);assert.match(query,/v\.status NOT IN \('staging','failed'\)/);assert.match(query,/e\.clinic_id=a\.clinic_id AND e\.document_id=a\.document_id/);assert.doesNotMatch(query,/DELETE FROM vetatiende_documental\.clinics/);assert.match(replacements,/ids\.document_public_a/);assert.doesNotMatch(query,/document_public_b|document_internal_a/);});
await test('--case rechaza un caso ajeno a la fase',async()=>assert.rejects(()=>ejecutarRuntime({manifestPath:prepared.manifest,phase:'management',caseId:'P-01',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl:runtimeFetch,verifyImpl:verifyMock}),/caso_invalido_para_fase/));
await test('--from=G-03 ejecuta setup y Management desde G-03 hasta G-09',async()=>{const checkpoints=[];let requests=0;const out=await ejecutarRuntime({manifestPath:prepared.manifest,phase:'management',fromId:'G-03',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl:async(...args)=>{requests++;return runtimeFetch(...args);},verifyImpl:async({checkpoint})=>{checkpoints.push(checkpoint);return verifyMock({checkpoint});}});assert.equal(out.ok,true);assert.equal(out.from,'G-03');assert.deepEqual(out.results.map(x=>x.id),['G-03','G-04','G-05','G-06','G-07','G-08','G-09']);assert.deepEqual(checkpoints,['setup','g03','g04','g05','g06','g07','g08','g09']);assert.equal(requests,6);});
await test('--from=G-06 ejecuta setup y únicamente G-06 a G-09',async()=>{const checkpoints=[];let requests=0;const out=await ejecutarRuntime({manifestPath:prepared.manifest,phase:'management',fromId:'G-06',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl:async(...args)=>{requests++;return runtimeFetch(...args);},verifyImpl:async({checkpoint})=>{checkpoints.push(checkpoint);return verifyMock({checkpoint});}});assert.equal(out.ok,true);assert.equal(out.from,'G-06');assert.deepEqual(out.results.map(x=>x.id),['G-06','G-07','G-08','G-09']);assert.deepEqual(checkpoints,['setup','g06','g07','g08','g09']);assert.equal(checkpoints.includes('prepare_g02'),false);assert.equal(requests,3);});
await test('--from conserva bloqueo tras el primer FAIL',async()=>{let requests=0;const failFirst=async()=>{requests++;return {status:500,json:async()=>({ok:false})};};const out=await ejecutarRuntime({manifestPath:prepared.manifest,phase:'management',fromId:'G-03',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl:failFirst,verifyImpl:verifyMock});assert.equal(out.ok,false);assert.equal(out.results[0].id,'G-03');assert.equal(out.results[0].status,'FAIL');assert.deepEqual(out.results.slice(1).map(x=>x.status),Array(6).fill('BLOCKED'));assert.equal(requests,1);});
await test('--from no se combina con --case',async()=>assert.rejects(()=>ejecutarRuntime({manifestPath:prepared.manifest,phase:'management',caseId:'G-02',fromId:'G-03',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl:runtimeFetch,verifyImpl:verifyMock}),/case_y_from_incompatibles/));
for(const [phase,expected] of Object.entries({management:9,public:5,internal:5,persistence:3}))await test(`fase ${phase} ejecutable con mocks`,async()=>{const out=await ejecutarRuntime({manifestPath:prepared.manifest,phase,confirm:'LAB029_RUNTIME_REAL',env,fetchImpl:runtimeFetch,verifyImpl:verifyMock});assert.equal(out.ok,true);assert.equal(out.results.length,expected);assert.ok(out.results.every(x=>x.status!=='FAIL'));});
await test('assertion fallida sigue siendo FAIL con tolerancia de latencia',async()=>{const badFetch=async()=>({status:200,json:async()=>({ok:true,message:'respuesta incorrecta'})});const out=await ejecutarRuntime({manifestPath:prepared.manifest,phase:'public',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl:badFetch,verifyImpl:verifyMock});assert.equal(out.ok,false);assert.equal(out.results[0].status,'FAIL');});
await test('fallo de transporte bloquea cascada management y conserva causa breve',async()=>{const transportFetch=async()=>{const error=new TypeError('fetch failed');error.cause={code:'ECONNREFUSED'};throw error;};const out=await ejecutarRuntime({manifestPath:prepared.manifest,phase:'management',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl:transportFetch,verifyImpl:verifyMock});assert.equal(out.results[0].status,'FAIL');assert.match(out.results[0].error,/ECONNREFUSED/);assert.deepEqual(out.results.slice(1).map(x=>x.status),Array(8).fill('BLOCKED'));});
await test('G-01 no acepta respuesta vacía como rechazo',async()=>{const emptyFetch=async()=>({status:200,json:async()=>({})});const out=await ejecutarRuntime({manifestPath:prepared.manifest,phase:'management',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl:emptyFetch,verifyImpl:verifyMock});assert.equal(out.results[0].status,'FAIL');assert.match(out.results[0].error,/contrato_invalido_no_bloqueado/);});
await test('cualquier FAIL management bloquea las pruebas dependientes',async()=>{let calls=0;const invalidAccepted=async()=>{calls++;return {status:200,json:async()=>({ok:true})};};const out=await ejecutarRuntime({manifestPath:prepared.manifest,phase:'management',confirm:'LAB029_RUNTIME_REAL',env,fetchImpl:invalidAccepted,verifyImpl:verifyMock});assert.equal(calls,1);assert.equal(out.results[0].status,'FAIL');assert.deepEqual(out.results.slice(1).map(x=>x.status),Array(8).fill('BLOCKED'));});
